UPDATE WORKSPACES
   SET WS_NAME = #{wsName, jdbcType=VARCHAR},
       WS_DESCRIPTION = #{wsDescription, jdbcType=VARCHAR},
       WS_TYPE = #{wsType, jdbcType=VARCHAR},
       JOIN_TYPE = #{joinType, jdbcType=VARCHAR}


           , WS_IMAGE_PATH = NULL
           , WS_IMAGE_ORIGINAL_PATH = NULL
           , WS_IMAGE_CROP_SCALE = NULL
           , WS_IMAGE_CROP_X = NULL
           , WS_IMAGE_CROP_Y = NULL


           , WS_IMAGE_PATH = #{wsImagePath, jdbcType=VARCHAR}
           , WS_IMAGE_ORIGINAL_PATH = #{wsImageOriginalPath, jdbcType=VARCHAR}
           , WS_IMAGE_CROP_SCALE = #{wsImageCropScale, jdbcType=NUMERIC}
           , WS_IMAGE_CROP_X = #{wsImageCropX, jdbcType=NUMERIC}
           , WS_IMAGE_CROP_Y = #{wsImageCropY, jdbcType=NUMERIC}


 WHERE WS_ID = #{wsId}


BEGIN
    BEGIN
        EXECUTE IMMEDIATE '
            CREATE TABLE WS_MEMBER_ACTIVITY_HISTORY (
                ACTIVITY_ID NUMBER(20) NOT NULL,
                WS_ID NUMBER(20) NOT NULL,
                USER_ID NUMBER(20) NOT NULL,
                ACTIVITY_TYPE VARCHAR2(20) NOT NULL,
                USER_NAME VARCHAR2(200),
                PROFILE_IMAGE_PATH VARCHAR2(1000),
                ACTIVITY_AT DATE DEFAULT SYSDATE NOT NULL,
                CONSTRAINT PK_WS_MEMBER_ACTIVITY PRIMARY KEY (ACTIVITY_ID)
            )';
    EXCEPTION WHEN OTHERS THEN
        IF SQLCODE != -955 THEN RAISE; END IF;
    END;

    BEGIN
        EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_WS_MEMBER_ACTIVITY START WITH 1 INCREMENT BY 1 NOCACHE';
    EXCEPTION WHEN OTHERS THEN
        IF SQLCODE != -955 THEN RAISE; END IF;
    END;
END;

