DELETE FROM PROJ_MEMBERS pm
 WHERE pm.USER_ID = #{userId}
   AND EXISTS (
       SELECT 1
         FROM PROJECTS p
        WHERE p.PROJ_ID = pm.PROJ_ID
          AND p.WS_ID = #{wsId}
          AND NVL(UPPER(p.PROJ_SCOPE), 'GROUP') = 'GROUP'
          AND NVL(p.STATUS, 'ACTIVE') = 'ACTIVE'
   )

