INSERT INTO WS_INVITATIONS (
    INVITE_ID, WS_ID, INVITER_ID, INVITEE_ID, STATUS, SENT_AT
)
SELECT GREATEST(
           SEQ_INVITE_ID.NEXTVAL,
           NVL((SELECT MAX(INVITE_ID) + 1 FROM WS_INVITATIONS), 1)
       ),
       #{wsId},
       #{inviterId},
       #{inviteeId},
       'PENDING',
       SYSDATE
  FROM DUAL
 WHERE NOT EXISTS (
           SELECT 1
             FROM WS_MEMBERS m
            WHERE m.WS_ID = #{wsId}
              AND m.USER_ID = #{inviteeId}
       )
   AND NOT EXISTS (
           SELECT 1
             FROM WS_INVITATIONS i
            WHERE i.WS_ID = #{wsId}
              AND i.INVITEE_ID = #{inviteeId}
              AND i.STATUS = 'PENDING'
       )

