mapper.delete:
DELETE FROM BOARD_POSTS
 WHERE WS_ID = #{wsId, jdbcType=NUMERIC}
   AND PROJ_ID IS NULL

DELETE FROM CONTENT_FILE_FOLDERS
 WHERE SCOPE_TYPE = 'GROUP'
   AND WS_ID = #{wsId, jdbcType=NUMERIC}

DELETE FROM CONTENT_FILES
 WHERE SCOPE_TYPE = 'GROUP'
   AND WS_ID = #{wsId, jdbcType=NUMERIC}

DELETE FROM CONTENT_REACTIONS cr
 WHERE (cr.CONTENT_TYPE = 'NOTE' AND cr.CONTENT_ID IN (
            SELECT n.NOTE_ID FROM NOTES n
             WHERE n.WS_ID = #{wsId, jdbcType=NUMERIC}
               AND n.PROJ_ID IS NULL
        ))
    OR (cr.CONTENT_TYPE = 'PHOTO' AND cr.CONTENT_ID IN (
            SELECT pp.PHOTO_ID FROM PHOTO_POSTS pp
             WHERE pp.SCOPE_TYPE = 'GROUP'
               AND pp.SCOPE_ID = #{wsId, jdbcType=NUMERIC}
        ))
    OR (cr.CONTENT_TYPE = 'BOARD' AND cr.CONTENT_ID IN (
            SELECT bp.POST_ID FROM BOARD_POSTS bp
             WHERE bp.WS_ID = #{wsId, jdbcType=NUMERIC}
               AND bp.PROJ_ID IS NULL
        ))
    OR (cr.CONTENT_TYPE = 'EVENT' AND cr.CONTENT_ID IN (
            SELECT e.EVENT_ID FROM EVENTS e
             WHERE e.WS_ID = #{wsId, jdbcType=NUMERIC}
               AND e.PROJ_ID IS NULL
        ))
    OR (cr.CONTENT_TYPE = 'POLL' AND cr.CONTENT_ID IN (
            SELECT p.POLL_ID FROM POLLS p
             WHERE p.WS_ID = #{wsId, jdbcType=NUMERIC}
               AND p.PROJ_ID IS NULL
        ))

DELETE FROM EVENTS
 WHERE WS_ID = #{wsId, jdbcType=NUMERIC}
   AND PROJ_ID IS NULL

DELETE FROM NOTES
 WHERE WS_ID = #{wsId, jdbcType=NUMERIC}
   AND PROJ_ID IS NULL

DELETE FROM NOTE_FOLDERS
 WHERE WS_ID = #{wsId, jdbcType=NUMERIC}
   AND PROJ_ID IS NULL

DELETE FROM PHOTO_ALBUMS
 WHERE SCOPE_TYPE = 'GROUP'
   AND SCOPE_ID = #{wsId, jdbcType=NUMERIC}

DELETE FROM PHOTO_POSTS
 WHERE SCOPE_TYPE = 'GROUP'
   AND SCOPE_ID = #{wsId, jdbcType=NUMERIC}

DELETE FROM POLLS
 WHERE WS_ID = #{wsId, jdbcType=NUMERIC}
   AND PROJ_ID IS NULL

DELETE FROM CONTENT_SHARES
 WHERE TARGET_TYPE = 'WS'
   AND TARGET_ID = #{wsId, jdbcType=NUMERIC}

mapper.select:
SELECT
    (SELECT COUNT(*) FROM NOTES n
      WHERE n.SCOPE_TYPE = 'WS'
        AND n.WS_ID = #{wsId, jdbcType=NUMERIC}
        AND n.USER_ID = #{userId, jdbcType=NUMERIC}
        AND NVL(n.DELETED_YN, 'N') = 'N') AS "NOTE_CNT",
    (SELECT COUNT(*) FROM PHOTOS ph
       JOIN PHOTO_POSTS pp ON pp.POST_ID = ph.POST_ID
      WHERE pp.SCOPE_TYPE IN ('WORKSPACE','GROUP')
        AND pp.SCOPE_ID = #{wsId, jdbcType=NUMERIC}
        AND ph.UPLOADED_BY = #{userId, jdbcType=NUMERIC}
        AND NVL(pp.DELETED_YN, 'N') = 'N') AS "PHOTO_CNT",
    (SELECT COUNT(*) FROM CONTENT_FILES f
      WHERE f.SCOPE_TYPE = 'GROUP'
        AND f.WS_ID = #{wsId, jdbcType=NUMERIC}
        AND f.CREATED_BY = #{userId, jdbcType=NUMERIC}
        AND f.DELETED_YN = 'N') AS "FILE_CNT"
FROM DUAL
